def main():
 assert (ROOT/'formal_evaluation_complete').exists();sym=json.loads((ROOT/'symmetric_analysis.json').read_text());allusd={'symmetric':sym};stop=(ROOT/'prerequisite_stop.json').exists();original=None
 if not stop:original=json.loads((ROOT/'original_analysis.json').read_text());allusd['original']=original
 conclusion={'prerequisite_passed':sym['prerequisite_passed'],'training_updates':0,'default_promoted':False,'parameter_scan':False,'rules_sha256':sha(ROOT/'classification_rules.json'),'individual95_intervals_not_simultaneous':True}
 if stop:
  assert not sym['prerequisite_passed'];conclusion.update(classification=('simulator_not_equivariant' if all(v['all_initial_trials_have20s_pairs'] for v in sym['gates'].values()) else 'prerequisite_unverified_due_to_censoring'),physical_fraction_P=None,recommendation='Next issue: investigate simulator equivariance, including contact-solver ordering and finite-precision state/clock effects. No extra experiments in this issue.',Phi_or_Gamma_not_inferred=True)
 else:
  g=original['paired_group_statistics']['forward_05'];S=g['S20_degrees'];D=g['D20_degrees'];den=original['cell_statistics']['0:forward_05']['absolute20_degrees']['mean'];P=None if den in [None,0] or S['mean'] is None else abs(S['mean'])/2/den;sd=sym['paired_group_statistics']['forward_05']['D20_degrees']['seeds'];od=D['seeds'];large=sum(x is not None and abs(x)>=20 for x in od);same=all(a is not None and b is not None and np.sign(a)==np.sign(b) for a,b in zip(od,sd));phi=not includes0(S) and P is not None and P>=.5 and includes0(sym['paired_group_statistics']['forward_05']['S20_degrees']);gamma=(P is not None and P<.5 or includes0(S)) and large>=3 and same
  if phi:label='Phi';nextstep='Recommend the symmetric model for a separately reviewed training/evaluation default change and check hardware parameters; this issue does not change defaults.'
